//! Deferred legacy worker/lease recovery fixtures; no browser/provider/model calls.
async fn legacy_fixture()->(PgConnection,Uuid,Value){let(mut c,_)=listing_fixture().await;let result=owner_import_call(&mut c,json!([owner_import_item("923456789012")])).await.unwrap();let job=result["job_ids"][0].as_str().unwrap().parse::<Uuid>().unwrap();let intent=owner_execution_call(&mut c,"/api/v1/execution/naukri/apply","POST",json!({"job_ids":[job]})).await.unwrap()[0].clone();(c,job,intent)}
async fn legacy_tick(c:&mut PgConnection)->Result<bool>{let config=Configuration::from_values(&queue_runtime_values()).unwrap();automated_apply_agents::execution::legacy_worker::tick(c,&config).await}
async fn legacy_prepare_claim(c:&mut PgConnection,claim:automated_apply_agents::execution::legacy_work::Claim)->Result<()>{let config=Configuration::from_values(&queue_runtime_values()).unwrap();automated_apply_agents::execution::legacy_prepare::prepare(c,claim,&config).await}
#[tokio::test(flavor="current_thread")]
#[ignore="requires dedicated disposable PostgreSQL harness"]
async fn legacy_preparation_claim_commits_before_packet_work_and_no_apply_admission_is_created(){
 let(mut c,job,intent)=legacy_fixture().await;let claim=automated_apply_agents::execution::legacy_work::claim(&mut c).await.unwrap().unwrap();assert_eq!(claim.id,intent["id"].as_str().unwrap().parse::<Uuid>().unwrap());let claimed=browser_pref(&mut c,&format!("exec:{}",claim.id)).await;assert_eq!(claimed["attempts"],1);assert_eq!(claimed["fence"],1);assert_eq!(sqlx::query_scalar::<_,i64>("SELECT count(*) FROM application_packets WHERE job_id=$1").bind(job).fetch_one(&mut c).await.unwrap(),0);legacy_prepare_claim(&mut c,claim).await.unwrap();let prepared=browser_pref(&mut c,&format!("exec:{}",claim.id)).await;assert!(matches!(prepared["state"].as_str(),Some("NEEDS_INPUT"|"READY_FOR_REVIEW")));assert!(prepared["lease_until"].is_null());assert_eq!(prepared["attempts"],0);assert!(prepared["packet_id"].as_str().is_some());assert_eq!(prepared["upload_preflight"]["browser_action_admitted"],false);assert_eq!(sqlx::query_scalar::<_,i64>("SELECT count(*) FROM application_packets WHERE job_id=$1").bind(job).fetch_one(&mut c).await.unwrap(),1);assert_eq!(sqlx::query_scalar::<_,i64>("SELECT count(*) FROM owner_preferences WHERE starts_with(key,'apply_budget:')").fetch_one(&mut c).await.unwrap(),0);assert!(automated_apply_agents::execution::legacy_work::claim(&mut c).await.unwrap().is_none());
}
#[tokio::test(flavor="current_thread")]
#[ignore="requires dedicated disposable PostgreSQL harness"]
async fn legacy_claim_idle_future_lease_and_question_only_work_never_wait_for_owner_lock(){
 let mut c=browser_fixture().await;browser_save(&mut c,"agent_conversation:primary",json!({"retained":"owner"})).await;let leased=owner_legacy(&mut c,"PREPARING").await;let question=owner_legacy(&mut c,"DISCOVERED").await;let mut question=question;question["question_only"]=json!(true);question["lease_until"]=Value::Null;browser_save(&mut c,&format!("exec:{}",question["id"].as_str().unwrap()),question).await;let before=browser_snapshot(&mut c).await;let mut owner=connection().await;let mut tx=owner.begin().await.unwrap();sqlx::query("SELECT key FROM owner_preferences WHERE key='agent_conversation:primary' FOR UPDATE").execute(&mut *tx).await.unwrap();sqlx::query("SET lock_timeout='100ms'").execute(&mut c).await.unwrap();assert!(automated_apply_agents::execution::legacy_work::claim(&mut c).await.unwrap().is_none());assert_eq!(browser_pref(&mut c,&format!("exec:{}",leased["id"].as_str().unwrap())).await,leased);assert_eq!(browser_snapshot(&mut c).await,before);tx.rollback().await.unwrap();
}
#[tokio::test(flavor="current_thread")]
#[ignore="requires dedicated disposable PostgreSQL harness"]
async fn legacy_expired_fill_and_submit_leases_are_quarantined_without_retry_or_refund(){
 let mut c=browser_fixture().await;let mut fill=owner_legacy(&mut c,"FILLING").await;fill["lease_until"]=json!("2000-01-01T00:00:00Z");let fkey=format!("exec:{}",fill["id"].as_str().unwrap());browser_save(&mut c,&fkey,fill.clone()).await;let mut submit=owner_legacy(&mut c,"SUBMITTING").await;submit["lease_until"]=json!("2000-01-01T00:00:00Z");let skey=format!("exec:{}",submit["id"].as_str().unwrap());browser_save(&mut c,&skey,submit.clone()).await;let unknown=owner_legacy(&mut c,"SUBMISSION_UNKNOWN").await;let quota=json!({"reservations":["spent-one","spent-two","spent-three"]});browser_save(&mut c,"apply_budget:naukri:retained",quota.clone()).await;assert!(automated_apply_agents::execution::legacy_work::claim(&mut c).await.unwrap().is_none());let filled=browser_pref(&mut c,&fkey).await;assert_eq!(filled["state"],"NEEDS_INPUT");assert_eq!(filled["diagnostic"],"fill_outcome_unknown_reinspect_manually");assert_eq!(filled["attempts"],fill["attempts"]);let submitted=browser_pref(&mut c,&skey).await;assert_eq!(submitted["state"],"SUBMISSION_UNKNOWN");assert_eq!(submitted["diagnostic"],"dispatch_outcome_unknown_no_replay");assert_eq!(submitted["attempts"],submit["attempts"]);assert_eq!(browser_pref(&mut c,&format!("exec:{}",unknown["id"].as_str().unwrap())).await,unknown);assert_eq!(browser_pref(&mut c,"apply_budget:naukri:retained").await,quota);
}
#[tokio::test(flavor="current_thread")]
#[ignore="requires dedicated disposable PostgreSQL harness"]
async fn legacy_preparation_owner_pause_fences_a_committed_claim_before_packet_creation(){
 let(mut c,job,intent)=legacy_fixture().await;let claim=automated_apply_agents::execution::legacy_work::claim(&mut c).await.unwrap().unwrap();owner_execution_call(&mut c,&format!("/api/v1/execution/{}/control",claim.id),"POST",json!({"expected_revision":intent["revision"],"action":"pause"})).await.unwrap();let before=browser_snapshot(&mut c).await;assert_eq!(legacy_prepare_claim(&mut c,claim).await.unwrap_err(),Failure("execution_lease_lost"));assert_eq!(browser_snapshot(&mut c).await,before);assert_eq!(sqlx::query_scalar::<_,i64>("SELECT count(*) FROM application_packets WHERE job_id=$1").bind(job).fetch_one(&mut c).await.unwrap(),0);
}
#[tokio::test(flavor="current_thread")]
#[ignore="requires dedicated disposable PostgreSQL harness"]
async fn legacy_preparation_confirmed_reviewed_mail_history_blocks_duplicate_work_without_mail_reads(){
 let(mut c,job,intent)=legacy_fixture().await;browser_save(&mut c,"gmail_application:fictional-reviewed",json!({"confirmed_application":true,"company":"Owner Reviewed Fictional Employer","role":"Rust Engineer","job_url":"https://www.naukri.com/job-listings-fictional-923456789012","expires_at":"2099-01-01T00:00:00Z","deleted":false})).await;let claim=automated_apply_agents::execution::legacy_work::claim(&mut c).await.unwrap().unwrap();legacy_prepare_claim(&mut c,claim).await.unwrap();let saved=browser_pref(&mut c,&format!("exec:{}",intent["id"].as_str().unwrap())).await;assert_eq!(saved["state"],"REJECTED");assert_eq!(saved["diagnostic"],"previous_application_or_unknown_submission");assert!(saved["lease_until"].is_null());assert_eq!(sqlx::query_scalar::<_,i64>("SELECT count(*) FROM application_packets WHERE job_id=$1").bind(job).fetch_one(&mut c).await.unwrap(),0);
}
#[tokio::test(flavor="current_thread")]
#[ignore="requires dedicated disposable PostgreSQL harness"]
async fn legacy_preparation_retry_limit_and_concurrent_claims_keep_one_durable_lease(){
 let(mut c,_job,intent)=legacy_fixture().await;let mut other=connection().await;let(one,two)=tokio::join!(automated_apply_agents::execution::legacy_work::claim(&mut c),automated_apply_agents::execution::legacy_work::claim(&mut other));assert_eq!(usize::from(one.as_ref().is_ok_and(|v|v.is_some()))+usize::from(two.as_ref().is_ok_and(|v|v.is_some())),1);let mut value=browser_pref(&mut c,&format!("exec:{}",intent["id"].as_str().unwrap())).await;value["attempts"]=json!(3);value["lease_until"]=json!("2000-01-01T00:00:00Z");browser_save(&mut c,&format!("exec:{}",intent["id"].as_str().unwrap()),value).await;assert!(automated_apply_agents::execution::legacy_work::claim(&mut c).await.unwrap().is_none());let saved=browser_pref(&mut c,&format!("exec:{}",intent["id"].as_str().unwrap())).await;assert_eq!(saved["state"],"FAILED_FINAL");assert_eq!(saved["diagnostic"],"retry_limit");
}
#[tokio::test(flavor="current_thread")]
#[ignore="requires dedicated disposable PostgreSQL harness"]
async fn legacy_worker_runs_explicit_preparation_with_application_queue_stopped_and_updates_only_observed_health(){
 let(mut c,job,intent)=legacy_fixture().await;let mut queue=browser_pref(&mut c,"application_queue_policy").await;queue["state"]=json!("STOPPED");browser_save(&mut c,"application_queue_policy",queue.clone()).await;assert!(legacy_tick(&mut c).await.unwrap());let saved=browser_pref(&mut c,&format!("exec:{}",intent["id"].as_str().unwrap())).await;assert!(saved["packet_id"].as_str().is_some());assert_eq!(browser_pref(&mut c,"application_queue_policy").await,queue);assert!(browser_pref(&mut c,"naukri_worker_health").await["heartbeat_at"].as_str().is_some());assert_eq!(sqlx::query_scalar::<_,i64>("SELECT count(*) FROM application_packets WHERE job_id=$1").bind(job).fetch_one(&mut c).await.unwrap(),1);assert_eq!(sqlx::query_scalar::<_,i64>("SELECT count(*) FROM owner_preferences WHERE starts_with(key,'apply_budget:')").fetch_one(&mut c).await.unwrap(),0);
}
#[tokio::test(flavor="current_thread")]
#[ignore="requires dedicated disposable PostgreSQL harness"]
async fn legacy_preparation_event_ack_failure_rolls_back_packet_and_retains_consumed_claim_attempt(){
 let(mut c,job,intent)=legacy_fixture().await;let claim=automated_apply_agents::execution::legacy_work::claim(&mut c).await.unwrap().unwrap();let before=browser_snapshot(&mut c).await;sqlx::raw_sql("CREATE FUNCTION fixture_legacy_event_drop() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF starts_with(NEW.key,'exec_event:') THEN RETURN NULL; END IF; RETURN NEW; END $$;CREATE TRIGGER fixture_legacy_event_drop BEFORE INSERT ON owner_preferences FOR EACH ROW EXECUTE FUNCTION fixture_legacy_event_drop()").execute(&mut c).await.unwrap();assert_eq!(legacy_prepare_claim(&mut c,claim).await.unwrap_err(),Failure("execution_write_ack_failed"));assert_eq!(browser_snapshot(&mut c).await,before);assert_eq!(browser_pref(&mut c,&format!("exec:{}",intent["id"].as_str().unwrap())).await["attempts"],1);assert_eq!(sqlx::query_scalar::<_,i64>("SELECT count(*) FROM application_packets WHERE job_id=$1").bind(job).fetch_one(&mut c).await.unwrap(),0);sqlx::raw_sql("DROP TRIGGER fixture_legacy_event_drop ON owner_preferences;DROP FUNCTION fixture_legacy_event_drop()").execute(&mut c).await.unwrap();
}
async fn legacy_schedule_fixture()->(PgConnection,Vec<Uuid>){
 let(mut c,_)=listing_fixture().await;sqlx::query("UPDATE candidate_profiles SET verified_skills='[\"Rust\"]'::jsonb,verified_experience_years=1,preferences=$1 WHERE singleton_key='primary'").bind(json!({"target_titles":["Rust Engineer"],"preferred_locations":["Remote"],"remote_preference":"remote","employment_types":["full_time"],"prioritize_startups":false,"company_stages":[],"excluded_companies":[],"excluded_titles":[],"excluded_keywords":[]})).execute(&mut c).await.unwrap();let mut items=Vec::new();for req in ["923456789012","923456789013","923456789014"]{let mut item=owner_import_item(req);item["employment_type"]=json!("full_time");item["posting_status"]=json!("active");item["observed_at"]=json!(chrono::Utc::now().to_rfc3339());item["posted_at"]=json!(chrono::Utc::now().to_rfc3339());items.push(item);}let result=owner_import_call(&mut c,json!(items)).await.unwrap();let jobs=result["job_ids"].as_array().unwrap().iter().map(|id|id.as_str().unwrap().parse().unwrap()).collect();(c,jobs)
}
#[tokio::test(flavor="current_thread")]
#[ignore="requires dedicated disposable PostgreSQL harness"]
async fn legacy_recurring_scheduler_reserves_only_preparation_budget_and_never_resumes_existing_intents(){
 let(mut c,_jobs)=legacy_schedule_fixture().await;let mut policy=owner_preparation_policy(&mut c).await;policy["max_preparations_per_day"]=json!(1);owner_execution_call(&mut c,"/api/v1/execution/naukri/automation/policy","PUT",json!({"expected_revision":0,"policy":policy})).await.unwrap();owner_execution_call(&mut c,"/api/v1/execution/naukri/automation/control","POST",json!({"expected_revision":1,"action":"start"})).await.unwrap();assert!(legacy_tick(&mut c).await.unwrap());let intents:Vec<Value>=sqlx::query_scalar("SELECT value FROM owner_preferences WHERE starts_with(key,'exec:')").fetch_all(&mut c).await.unwrap();assert_eq!(intents.len(),1);assert_eq!(intents[0]["automation_revision"],2);let reserved:Value=sqlx::query_scalar("SELECT value FROM owner_preferences WHERE starts_with(key,'nau_budget:')").fetch_one(&mut c).await.unwrap();assert_eq!(reserved["reserved"],1);let id=intents[0]["id"].as_str().unwrap();let current=browser_pref(&mut c,&format!("exec:{id}")).await;owner_execution_call(&mut c,&format!("/api/v1/execution/{id}/control"),"POST",json!({"expected_revision":current["revision"],"action":"pause"})).await.unwrap();let paused=browser_pref(&mut c,&format!("exec:{id}")).await;let mut automation=browser_pref(&mut c,"naukri_automation").await;automation["next_check_at"]=json!("2000-01-01T00:00:00Z");browser_save(&mut c,"naukri_automation",automation).await;legacy_tick(&mut c).await.unwrap();assert_eq!(browser_pref(&mut c,&format!("exec:{id}")).await,paused);assert_eq!(sqlx::query_scalar::<_,i64>("SELECT count(*) FROM owner_preferences WHERE starts_with(key,'exec:')").fetch_one(&mut c).await.unwrap(),1);assert_eq!(sqlx::query_scalar::<_,i64>("SELECT count(*) FROM owner_preferences WHERE starts_with(key,'apply_budget:')").fetch_one(&mut c).await.unwrap(),0);
}
#[tokio::test(flavor="current_thread")]
