#[tokio::test(flavor="current_thread")]
#[ignore="requires dedicated disposable PostgreSQL harness"]
async fn full_host_quiesce_also_pauses_running_legacy_preparation_when_application_queue_is_already_stopped(){
 let(mut c,_job,intent)=legacy_fixture().await;let mut queue=browser_pref(&mut c,"application_queue_policy").await;queue["state"]=json!("STOPPED");browser_save(&mut c,"application_queue_policy",queue.clone()).await;browser_save(&mut c,"naukri_automation",json!({"state":"RUNNING","revision":3,"policy":null})).await;let config=Arc::new(Configuration::from_values(&host_values()).unwrap());let control=config.connect(false).await.unwrap();let api=Api::new(config,control,Wake::default());server::quiesce(&api).await.unwrap();assert_eq!(browser_pref(&mut c,"application_queue_policy").await,queue);let legacy=browser_pref(&mut c,"naukri_automation").await;assert_eq!(legacy["state"],"PAUSED");assert_eq!(legacy["revision"],4);assert_eq!(browser_pref(&mut c,&format!("exec:{}",intent["id"].as_str().unwrap())).await["state"],"PAUSED");server::quiesce(&api).await.unwrap();assert_eq!(browser_pref(&mut c,"naukri_automation").await,legacy);
}
